package main

import (
	"errors"
	"sync"
	"time"
)

// ErrNotFound is returned when a session id is unknown or has expired.
var ErrNotFound = errors.New("session not found")

// ErrConflict is returned when a session id already exists.
var ErrConflict = errors.New("session already exists")

// ErrInvalidID is returned when a session id is malformed.
var ErrInvalidID = errors.New("invalid session id")

// ErrUserAtCap is returned when a user already holds the maximum number
// of live sessions.
var ErrUserAtCap = errors.New("user at session cap")

// Session is one signed-in user.
type Session struct {
	ID       string
	User     string
	Created  time.Time
	LastSeen time.Time
}

// Store keeps sessions in memory. Everything is lost when the process exits.
type Store struct {
	mu       sync.RWMutex
	sessions map[string]Session
	ttl      time.Duration
	now      func() time.Time
}

// NewStore returns an empty store. Sessions idle for longer than ttl expire.
func NewStore(ttl time.Duration) *Store {
	return &Store{
		sessions: map[string]Session{},
		ttl:      ttl,
		now:      time.Now,
	}
}

// Create records a new session for a user.
func (s *Store) Create(id string, user string) Session {
	s.mu.Lock()
	defer s.mu.Unlock()
	at := s.now()
	session := Session{ID: id, User: user, Created: at, LastSeen: at}
	s.sessions[id] = session
	return session
}

// Get returns a live session and refreshes its last-seen time. An expired
// session is dropped and reported as missing.
func (s *Store) Get(id string) (Session, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	session, ok := s.sessions[id]
	if !ok {
		return Session{}, ErrNotFound
	}
	if s.now().Sub(session.LastSeen) > s.ttl {
		delete(s.sessions, id)
		return Session{}, ErrNotFound
	}
	session.LastSeen = s.now()
	s.sessions[id] = session
	return session, nil
}

// Delete removes a session. Deleting an unknown id is not an error.
func (s *Store) Delete(id string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.sessions, id)
}

// Len reports how many sessions are held.
func (s *Store) Len() int {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return len(s.sessions)
}

package main

import (
	"errors"
	"testing"
	"time"
)

func TestStoreCreateAndGet(t *testing.T) {
	store := NewStore(time.Minute)
	created := store.Create("abc", "ada")
	if created.User != "ada" {
		t.Fatalf("created user = %q, want ada", created.User)
	}
	found, err := store.Get("abc")
	if err != nil {
		t.Fatalf("Get: %v", err)
	}
	if found.ID != "abc" || found.User != "ada" {
		t.Fatalf("found session = %+v, want abc/ada", found)
	}
	if store.Len() != 1 {
		t.Fatalf("store length = %d, want 1", store.Len())
	}
}

func TestStoreExpiresIdleSession(t *testing.T) {
	store := NewStore(time.Minute)
	clock := time.Now()
	store.now = func() time.Time { return clock }
	store.Create("abc", "ada")

	clock = clock.Add(2 * time.Minute)
	if _, err := store.Get("abc"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("Get after ttl = %v, want ErrNotFound", err)
	}
	if store.Len() != 0 {
		t.Fatalf("expired session was not dropped: length = %d", store.Len())
	}
}

